sys_ui_action.script:
// Validate mandatory fields on server
if (current.u_employee.nil()) {
    gs.addErrorMessage('Please select an Employee before requesting.');
    action.setReturnURL(current);
} else if (current.u_due_date.nil()) {
    gs.addErrorMessage('Please provide a Due Date before requesting.');
    action.setReturnURL(current);
} else if (current.u_document_type.nil()) {
    gs.addErrorMessage('Please select a Document Type before requesting.');
    action.setReturnURL(current);
} else {
    // Set status to requested
    current.setValue('u_status', 'requested');

    // Insert new record or update existing
    var sysId = current.isNewRecord() ? current.insert() : current.update();

    if (sysId) {
        gs.addInfoMessage('Document request submitted successfully.');

        var targetEmployee = current.getValue('u_employee');
        if (targetEmployee) {
            action.setRedirectURL('x_2182380_pwcnow_employee_document_list.do?sysparm_view=hr_doc_request&sysparm_query=u_employee=' + targetEmployee);
        } else {
            action.setRedirectURL('x_2182380_pwcnow_employee_document_list.do?sysparm_view=hr_doc_request');
        }
    } else {
        gs.addErrorMessage('Failed to save record. Check table ACL permissions.');
    }
}
